import{_ as s,o as a,c as o,a3 as n}from"./chunks/framework.Cc-oPviL.js";const h=JSON.parse('{"title":"02 · 事务与 ACID","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/db/02.md","filePath":"bagu/db/02.md"}'),l={name:"bagu/db/02.md"};function e(r,t,d,p,i,g){return a(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="_02-·-事务与-acid" tabindex="-1">02 · 事务与 ACID <a class="header-anchor" href="#_02-·-事务与-acid" aria-label="Permalink to &quot;02 · 事务与 ACID&quot;">​</a></h1><blockquote><p>事务这块最容易背成四个字母。真正的问题是：<strong>数据库凭什么敢说&quot;这条数据一定不会丢&quot;</strong>？</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>事务把&quot;多条操作&quot;打包成&quot;一个不可分割的整体&quot;：<strong>要么全做，要么全不做，且做完就一定能查到</strong>。</p><h2 id="生活类比-银行转账" tabindex="-1">生活类比：银行转账 <a class="header-anchor" href="#生活类比-银行转账" aria-label="Permalink to &quot;生活类比：银行转账&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A 给 B 转 100 元 = 两个动作：</span></span>
<span class="line"><span>  ① A 的余额 -100</span></span>
<span class="line"><span>  ② B 的余额 +100</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果 ① 做完系统崩了：</span></span>
<span class="line"><span>  没有事务 &gt; A 少了 100，B 没收到，钱凭空消失</span></span>
<span class="line"><span>  有事务   &gt; ① 被撤销（undo），或者 ② 被补做（redo）</span></span></code></pre></div><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、acid-到底谁负责" tabindex="-1">一、ACID 到底谁负责 <a class="header-anchor" href="#一、acid-到底谁负责" aria-label="Permalink to &quot;一、ACID 到底谁负责&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字母</th><th>含义</th><th>靠什么实现</th></tr></thead><tbody><tr><td><strong>A</strong> 原子性</td><td>全做或全不做</td><td><strong>undo log</strong>（记录旧值，回滚时反向操作）</td></tr><tr><td><strong>C</strong> 一致性</td><td>数据满足约束（余额不能为负、外键有效）</td><td><strong>不是数据库单独实现的</strong>，是 A+I+D + 应用逻辑共同保证的结果</td></tr><tr><td><strong>I</strong> 隔离性</td><td>并发事务互不干扰</td><td><strong>锁 + MVCC</strong>（见 03、04 篇）</td></tr><tr><td><strong>D</strong> 持久性</td><td>提交后即使断电也不丢</td><td><strong>redo log</strong>（WAL，先写日志再写数据）</td></tr></tbody></table><p><strong>最重要的认知</strong>：<strong>C 是目标，A、I、D 是手段</strong>。</p><p>面试问&quot;ACID 怎么实现&quot;，答&quot;A 靠 undo、D 靠 redo、I 靠锁和 MVCC、C 是前三者加上业务约束共同保证的结果&quot;——这个层次就对了。如果答&quot;C 靠……&quot;，说明没理解。</p><h3 id="二、undo-log-怎么撤销" tabindex="-1">二、undo log：怎么撤销 <a class="header-anchor" href="#二、undo-log-怎么撤销" aria-label="Permalink to &quot;二、undo log：怎么撤销&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>执行 UPDATE user SET balance = 900 WHERE id = 1;  （原值 1000）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>undo log 记录：</span></span>
<span class="line"><span>  &quot;id=1 的 balance 原来是 1000&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>回滚时：UPDATE user SET balance = 1000 WHERE id = 1</span></span></code></pre></div><p><strong>undo log 还兼职做 MVCC</strong>：它保存了旧版本，所以其他事务能读到&quot;修改前的值&quot;。这就是 03 篇版本链的来源。</p><p><strong>undo log 是逻辑日志</strong>：记录&quot;做了什么操作&quot;，回滚时执行相反操作。不是物理的&quot;页变成了什么样&quot;。</p><h3 id="三、redo-log-怎么保证不丢" tabindex="-1">三、redo log：怎么保证不丢 <a class="header-anchor" href="#三、redo-log-怎么保证不丢" aria-label="Permalink to &quot;三、redo log：怎么保证不丢&quot;">​</a></h3><p><strong>核心问题</strong>：修改数据要先改 Buffer Pool（内存），再刷到磁盘。但如果每次提交都刷盘，太慢（一次随机 IO 10ms）。</p><p><strong>WAL（Write-Ahead Logging）的做法</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 修改 Buffer Pool（内存里的页）</span></span>
<span class="line"><span>② 把&quot;改了什么&quot;追加到 redo log（顺序写，很快）</span></span>
<span class="line"><span>③ redo log 刷盘（fsync）&gt; 此时就可以回复客户端&quot;提交成功&quot;</span></span>
<span class="line"><span>④ 数据页在后台慢慢刷盘（异步，不阻塞）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果断电：</span></span>
<span class="line"><span>  Buffer Pool 里的修改丢了，但 redo log 已经落盘</span></span>
<span class="line"><span>  重启时重放 redo log，把丢失的修改补回来</span></span></code></pre></div><p><strong>为什么快</strong>：<strong>顺序写 vs 随机写</strong>。</p><ul><li>直接改数据页：要找到那一页在磁盘的位置，随机写（10ms 级）</li><li>写 redo log：追加到文件末尾，顺序写（0.1ms 级）</li></ul><p><strong>关键参数</strong> <code>innodb_flush_log_at_trx_commit</code>：</p><table tabindex="0"><thead><tr><th>值</th><th>行为</th><th>丢失风险</th></tr></thead><tbody><tr><td>1（默认）</td><td>每次提交都 fsync</td><td>不丢（最安全）</td></tr><tr><td>0</td><td>每秒刷一次</td><td>丢 1 秒</td></tr><tr><td>2</td><td>写到 OS 缓存，每秒刷</td><td>丢 1 秒（OS 崩）/ 不丢（只是 MySQL 崩）</td></tr></tbody></table><h3 id="四、binlog-server-层的日志" tabindex="-1">四、binlog：Server 层的日志 <a class="header-anchor" href="#四、binlog-server-层的日志" aria-label="Permalink to &quot;四、binlog：Server 层的日志&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>redo log</th><th>binlog</th></tr></thead><tbody><tr><td>层级</td><td>InnoDB 引擎层</td><td>Server 层</td></tr><tr><td>内容</td><td>物理日志（&quot;某页某偏移改成了什么&quot;）</td><td>逻辑日志（&quot;执行了哪条 SQL&quot;）</td></tr><tr><td>写入</td><td>循环写（固定大小，覆盖旧内容）</td><td>追加写（不覆盖）</td></tr><tr><td>用途</td><td><strong>崩溃恢复</strong></td><td><strong>主从复制、数据恢复</strong></td></tr></tbody></table><p><strong>为什么两个都要</strong>：</p><ul><li>redo log 是 InnoDB 自己的，循环写，只能用于崩溃恢复。</li><li>binlog 是 Server 层的，所有引擎共用，追加写，能用于主从同步和按时间点恢复。</li></ul><h3 id="五、两阶段提交-这是最常考的一致性细节" tabindex="-1">五、两阶段提交（这是最常考的一致性细节） <a class="header-anchor" href="#五、两阶段提交-这是最常考的一致性细节" aria-label="Permalink to &quot;五、两阶段提交（这是最常考的一致性细节）&quot;">​</a></h3><p><strong>问题</strong>：一次提交要写两个日志（redo 和 binlog），怎么保证两个都成功？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果先写 redo 再写 binlog，写完 redo 后崩了：</span></span>
<span class="line"><span>  &gt; redo 说&quot;已提交&quot;，binlog 没有</span></span>
<span class="line"><span>  &gt; 主库有这条数据，从库（靠 binlog 同步）没有 &gt; 主从不一致</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果先写 binlog 再写 redo，写完 binlog 后崩了：</span></span>
<span class="line"><span>  &gt; binlog 有，主库没有 &gt; 从库多了一条数据 &gt; 不一致</span></span></code></pre></div><p><strong>解法：两阶段提交</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 写 redo log，标记为 prepare 状态</span></span>
<span class="line"><span>② 写 binlog</span></span>
<span class="line"><span>③ 写 redo log，标记为 commit 状态</span></span>
<span class="line"><span></span></span>
<span class="line"><span>崩溃恢复时的判断：</span></span>
<span class="line"><span>  - redo 是 prepare，binlog 完整 &gt; 提交（步骤 ③ 没做完，补做）</span></span>
<span class="line"><span>  - redo 是 prepare，binlog 不完整 &gt; 回滚</span></span></code></pre></div><p><strong>关键</strong>：<strong>用 binlog 是否完整来决定 redo 该提交还是回滚</strong>。这样两个日志要么都生效，要么都不生效。</p><h3 id="六、事务的隔离性与异常-为-03-篇铺垫" tabindex="-1">六、事务的隔离性与异常（为 03 篇铺垫） <a class="header-anchor" href="#六、事务的隔离性与异常-为-03-篇铺垫" aria-label="Permalink to &quot;六、事务的隔离性与异常（为 03 篇铺垫）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>异常</th><th>现象</th></tr></thead><tbody><tr><td><strong>脏读</strong></td><td>读到了别的事务<strong>未提交</strong>的数据（对方可能回滚）</td></tr><tr><td><strong>不可重复读</strong></td><td>同一事务内，两次读同一行，结果不同（别人改了并提交）</td></tr><tr><td><strong>幻读</strong></td><td>同一事务内，两次<strong>范围查询</strong>，行数不同（别人插入并提交）</td></tr></tbody></table><p><strong>不可重复读 vs 幻读的区别</strong>：</p><ul><li>不可重复读：<strong>同一行</strong>的值变了（UPDATE）</li><li>幻读：<strong>行数</strong>变了（INSERT/DELETE）</li></ul><p><strong>四个隔离级别</strong>（详见 03 篇）：</p><table tabindex="0"><thead><tr><th>级别</th><th>脏读</th><th>不可重复读</th><th>幻读</th></tr></thead><tbody><tr><td>读未提交</td><td>✅ 可能</td><td>✅</td><td>✅</td></tr><tr><td>读已提交</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>可重复读（MySQL 默认）</td><td>❌</td><td>❌</td><td>⚠️ 理论上可能，InnoDB 用间隙锁基本解决</td></tr><tr><td>串行化</td><td>❌</td><td>❌</td><td>❌</td></tr></tbody></table><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果没有-undo-log" tabindex="-1">反事实 1：如果没有 undo log <a class="header-anchor" href="#反事实-1-如果没有-undo-log" aria-label="Permalink to &quot;反事实 1：如果没有 undo log&quot;">​</a></h3><p>事务执行到一半失败，无法回滚。数据处于&quot;一半改了、一半没改&quot;的中间状态，业务逻辑完全错乱。</p><p>而且<strong>没有 undo log 就没有 MVCC</strong>——因为 MVCC 要靠 undo log 里的旧版本。</p><h3 id="反事实-2-如果没有-redo-log-每次直接刷数据页" tabindex="-1">反事实 2：如果没有 redo log（每次直接刷数据页） <a class="header-anchor" href="#反事实-2-如果没有-redo-log-每次直接刷数据页" aria-label="Permalink to &quot;反事实 2：如果没有 redo log（每次直接刷数据页）&quot;">​</a></h3><p>每次提交都要随机写磁盘。一个事务改 10 行、分布在 5 个页上 &gt; 5 次随机 IO = 50ms。TPS 只有 20。</p><p>有了 redo log（顺序写）：一次追加 ≈ 0.1ms。TPS 能到几千。</p><p><strong>redo log 的本质是&quot;把随机写变成顺序写&quot;</strong>——这是数据库性能的核心机密。</p><h3 id="反事实-3-如果没有两阶段提交" tabindex="-1">反事实 3：如果没有两阶段提交 <a class="header-anchor" href="#反事实-3-如果没有两阶段提交" aria-label="Permalink to &quot;反事实 3：如果没有两阶段提交&quot;">​</a></h3><p>主从数据不一致。而且这种不一致是<strong>静默的</strong>——不会报错，只在某天发现&quot;从库少了 3 条数据&quot;，且无法追溯是哪三条。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：ACID 分别怎么实现？</strong></p><blockquote><p>A &gt; undo log（记录旧值，反向操作回滚） D &gt; redo log（WAL，先写日志再刷数据页） I &gt; 锁 + MVCC C &gt; <strong>不是单独实现的</strong>，是 A/I/D 加上业务约束共同保证的结果 <strong>这个&quot; C 不是数据库实现的&quot;是加分点</strong>。</p></blockquote><p><strong>Q：redo log 和 binlog 的区别？</strong></p><blockquote><p>层级（引擎层 vs Server 层）、内容（物理 vs 逻辑）、写入方式（循环写 vs 追加写）、用途（崩溃恢复 vs 主从复制）。</p></blockquote><p><strong>Q：为什么需要两阶段提交？</strong></p><blockquote><p>因为要写两个日志，必须保证原子性。用&quot;redo prepare &gt; binlog &gt; redo commit&quot;，崩溃时根据 binlog 是否完整决定提交还是回滚。</p></blockquote><p><strong>Q：WAL 是什么？为什么快？</strong></p><blockquote><p>Write-Ahead Logging：先写日志再写数据页。快的原因是<strong>顺序写替代随机写</strong>——日志追加到文件末尾，而数据页要定位到磁盘随机位置。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务怎么保证原子性？</span></span>
<span class="line"><span>  &gt; undo log 记了什么？（旧值）</span></span>
<span class="line"><span>    &gt; 那持久性呢？（redo log）</span></span>
<span class="line"><span>      &gt; redo log 为什么比直接改数据页快？（顺序写 vs 随机写）</span></span>
<span class="line"><span>        &gt; 那 binlog 呢？（Server 层，用于主从）</span></span>
<span class="line"><span>          &gt; 两个日志怎么保证一致？（两阶段提交）</span></span>
<span class="line"><span>            &gt; 崩溃时怎么判断？（redo 是 prepare 且 binlog 完整 &gt; 提交）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/04">IO 模型与零拷贝：等设备的时候，CPU 在干什么</a>：fsync、页缓存、顺序写 vs 随机写，是 WAL 性能的来源</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/03">调度与并发同步：CPU 分给谁，共享数据谁先动</a>：事务的隔离性靠锁，锁理论同源</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/03">隔离级别与 MVCC</a>：undo log 是 MVCC 版本链的载体</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/04">锁与死锁</a>：隔离级别的实现依赖锁</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/05">SQL 执行与优化</a>：长事务会拖住 undo log 的清理（purge），导致版本链过长</li><li><strong>&gt; 影响</strong> 分布式：两阶段提交（2PC）是分布式事务的基础，也是它的性能瓶颈</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么说&quot;一致性（C）不是数据库实现的&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>一致性是业务层面的目标，不是数据库能单独保证的</strong>。</p><p>数据库能保证的：</p><ul><li>原子性（要么全做要么全不做）</li><li>隔离性（并发不互相干扰）</li><li>持久性（提交了就不丢）</li></ul><p>但&quot;数据符合业务规则&quot;这件事，数据库管不了。比如：</p><ul><li>&quot;账户余额不能为负&quot;——数据库不知道这个规则，除非你写 <code>CHECK</code> 约束或触发器。</li><li>&quot;A 转账给 B，总额不变&quot;——这需要应用层保证两个 UPDATE 在同一个事务里。</li></ul><p><strong>准确说法</strong>：A、I、D 是数据库提供的<strong>手段</strong>，C 是这些手段加上<strong>业务约束</strong>共同达成的<strong>结果</strong>。</p><p>面试这样答，比背&quot;一致性由原子性隔离性持久性共同保证&quot;更清楚。</p></details><p><strong>Q2：redo log 循环写，写满了怎么办？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>redo log 是固定大小的环形文件（比如 4 个 1GB 的文件），有一个&quot;写指针&quot;和一个&quot;检查点指针&quot;。</p><ul><li>写指针往前走，记录新的日志。</li><li>检查点指针表示&quot;这个位置之前的日志对应的数据页，已经刷到磁盘了，可以覆盖&quot;。</li></ul><p><strong>写满时</strong>：写指针追上检查点指针 &gt; 必须<strong>停下来，强制把 Buffer Pool 里的脏页刷盘</strong>，推进检查点，腾出空间。</p><p>这就是为什么&quot;redo log 太小会导致性能抖动&quot;——频繁触发强制刷盘，把异步刷盘变成了同步等待。</p><p><strong>工程建议</strong>：redo log 不要设太小，让检查点推进有足够缓冲。</p></details><p><strong>Q3：既然有 redo log，为什么还需要 binlog？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为它们<strong>服务于不同的目的</strong>，不能互相替代：</p><table tabindex="0"><thead><tr><th></th><th>redo log</th><th>binlog</th></tr></thead><tbody><tr><td>谁需要</td><td>只有 InnoDB 自己</td><td>整个 MySQL Server（包括主从、备份工具）</td></tr><tr><td>能干什么</td><td>崩溃恢复（重放未刷盘的修改）</td><td>主从复制（从库重放主库的 binlog）、按时间点恢复</td></tr><tr><td>写入方式</td><td>循环写，会被覆盖</td><td>追加写，永久保留（直到手动清理）</td></tr><tr><td>内容</td><td>物理（页级别的修改）</td><td>逻辑（SQL 语句或行变更）</td></tr></tbody></table><p><strong>关键</strong>：redo log 会被覆盖，所以<strong>不能用来做主从同步</strong>（从库落后太多就丢了）。binlog 追加写且可长期保留，才能支撑&quot;从库延迟几小时再同步&quot;。</p><p>另外，redo log 是 InnoDB 特有的，如果换成 MyISAM 引擎就没有了——但 binlog 在 Server 层，所有引擎都有。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;转账&quot;类比会让人以为事务只用于多表操作</strong>。单表单行也能用事务，只要需要原子性。</li><li><strong>undo log 不只是&quot;回滚用&quot;</strong>。它还承担 MVCC 的&quot;旧版本&quot;职责，所以长事务会导致 undo log 无法清理、版本链过长、磁盘暴涨。</li><li><strong>redo log 不是&quot;备份&quot;</strong>。它是&quot;还没刷到数据页的修改记录&quot;，一旦对应数据页刷盘，那部分 redo 就没用了（可以被覆盖）。</li><li><strong>两阶段提交（数据库内部）≠ 分布式事务的 2PC</strong>。虽然思想相似，但一个是&quot;两个日志&quot;，一个是&quot;多个节点&quot;。面试时要说清是哪个。</li><li><strong>隔离级别越高越好是错的</strong>。串行化性能极差，实际业务几乎不用；MySQL 默认的可重复读已经能满足绝大多数场景。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出 ACID 四个字母各由什么机制实现，并解释&quot;为什么 C 不是数据库实现的&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说清 undo log 的两个作用（回滚 + MVCC 旧版本）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能用&quot;顺序写 vs 随机写&quot;解释 WAL 为什么快</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能对比 redo log 和 binlog 的四个区别（层级、内容、写入、用途）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能讲清两阶段提交的流程，以及崩溃时怎么判断该提交还是回滚</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能区分脏读、不可重复读、幻读，并说出各自的成因（UPDATE vs INSERT）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能说出 redo log 写满时会发生什么</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,73)])])}const c=s(l,[["render",e]]);export{h as __pageData,c as default};
